wealthSimulatorCss:
.wealth-sim-toggle-btn { display: inline-flex; align-items: center; gap: 6px; padding: 6px 12px; border-radius: 999px; border: 1px solid var(--border-accent); background: rgba(var(--primary-rgb), 0.12); color: var(--primary); font-family: var(--font-body); font-size: 12px; font-weight: 700; cursor: var(--cursor-pointer); transition: transform 0.2s var(--ease), background-color 0.2s var(--ease), box-shadow 0.2s var(--ease); }
.health-telemetry-strip { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 10px; margin-bottom: 16px; }
.health-telemetry-pill { background: var(--input-bg); border: 1px solid var(--border); border-radius: 12px; padding: 10px 14px; display: flex; flex-direction: column; gap: 6px; }
.health-telemetry-bar { width: 100%; height: 5px; border-radius: 999px; background: rgba(var(--ink-rgb), 0.08); overflow: hidden; }
.health-telemetry-fill { height: 100%; width: var(--score-pct, 75%); background: var(--primary-gradient); border-radius: 999px; transition: width 0.35s var(--ease); }
.wealth-simulator-drawer { margin-top: 16px; padding: 20px; border-radius: 16px; background: var(--card-bg); border: 1px solid var(--border-accent); box-shadow: var(--shadow-premium); }
.wealth-sim-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 18px; margin-top: 14px; }
.wealth-sim-outcomes { display: grid; grid-template-columns: repeat(auto-fit, minmax(175px, 1fr)); gap: 12px; margin-top: 16px; }

